import static org.junit.jupiter.api.Assertions.assertEquals;

import com.wolinski.shop.ShopConfig;
import com.wolinski.shop.money.Money;
import com.wolinski.shop.orders.api.OrderFacade;
import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import org.junit.jupiter.api.Test;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;

class OrderServiceExpireTest {

    @Test
    void cancelsOnlyPlacedOrdersOlderThanThirtyDays() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);
            Instant now = shop.getBean(Clock.class).instant();

            String stale = orders.place("c-1", Money.pln(1000), now.minus(Duration.ofDays(31)));
            String fresh = orders.place("c-2", Money.pln(1000), now.minus(Duration.ofDays(29)));
            String staleConfirmed = orders.place("c-3", Money.pln(1000), now.minus(Duration.ofDays(60)));
            orders.confirm(staleConfirmed);

            assertEquals(1, orders.expireStale());

            assertEquals("CANCELLED", orders.summary(stale).status());
            assertEquals("PLACED", orders.summary(fresh).status());
            assertEquals("CONFIRMED", orders.summary(staleConfirmed).status());
            assertEquals(0, orders.expireStale());
        }
    }
}
